func matchPreservedSectionIdx(sections []SectionData, p preservedSection, claimed map[int]bool) int {
  if p.componentID != "" { for i := range sections { if !claimed[i] && sections[i].ComponentID == p.componentID { return i } } }
  if p.slot != "" {
    for i := range sections { if !claimed[i] && sections[i].ComponentName == p.slot { return i } }
    if norm := NormalizeComponentFunction(p.slot); norm != "" { for i := range sections { if !claimed[i] && sections[i].ComponentName != "" && NormalizeComponentFunction(sections[i].ComponentName) == norm { return i } } }
  }
  if p.componentFunction != "" { for i := range sections { if !claimed[i] && sections[i].ComponentName == p.componentFunction { return i } } }
  return -1
}

claimed := make(map[int]bool, len(preserved))
for _, p := range preserved {
  matchedIdx := matchPreservedSectionIdx(sections, p, claimed)
  if matchedIdx >= 0 { claimed[matchedIdx] = true }
  switch { /* unchanged: keep / splice / re-append */ }
}
